const assets = {"public/assets/detetive/frame_00.png": "", "public/assets/detetive/frame_09.png": "", "public/assets/detetive/frame_12.png": "", "public/assets/detetive/frame_04.png": "", "public/assets/detetive/frame_13.png": "", "public/assets/detetive/frame_07.png": "", "public/assets/detetive/frame_14.png": "", "public/assets/detetive/frame_02.png": "", "public/assets/detetive/frame_03.png": "", "public/assets/detetive/frame_10.png": "", "public/assets/detetive/frame_06.png": "", "public/assets/detetive/frame_15.png": "", "public/assets/detetive/frame_08.png": "", "public/assets/detetive/frame_11.png": "", "public/assets/detetive/frame_05.png": "", "public/assets/detetive/frame_01.png": "", "public/assets/detetive_derrota/frame_06.png": "", "public/assets/detetive_derrota/frame_04.png": "", "public/assets/detetive_derrota/frame_01.png": "", "public/assets/detetive_derrota/frame_05.png": "", "public/assets/detetive_derrota/frame_02.png": "", "public/assets/detetive_derrota/frame_07.png": "", "public/assets/detetive_derrota/frame_00.png": "", "public/assets/detetive_derrota/frame_03.png": ""};

const fs = require("fs");
const path = require("path");
const { execSync } = require("child_process");

console.log("--> Restaurando todas as animacoes do detetive (vitoria, derrota, briefing)...");
for (const [filePath, b64] of Object.entries(assets)) {
    const dir = path.dirname(filePath);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(filePath, Buffer.from(b64, "base64"));
    console.log(" Gravado: " + filePath);
}

console.log("\n--> Subindo para o GitHub e Surge...");
try {
    execSync("git add public/assets/detetive public/assets/detetive_derrota", { stdio: "inherit" });
    execSync("git commit -m \"feat: adicionar frames completos de animacao do detetive\"", { stdio: "inherit" });
    execSync("git push origin master --force", { stdio: "inherit" });
    execSync("npm run deploy", { stdio: "inherit" });
    console.log("\n SUCESSO! Todas as animacoes do detetive estao publicadas no Surge!");
} catch (e) {
    console.log("Erro ao enviar:", e.message);
}
